  str_season_maze_s1_help_title_604 = "Orb Mimpi",
  str_season_maze_s1_help_title_605 = "Item Bantuan Dream Aid",
  str_season_maze_s1_help_disc_101 = "Elemen-elemen tidak stabil dari mimpi-mimpi masa lalu masih mengendap di alam mimpi, siap untuk menyerang kenyataan kapan saja. Dengan bantuan Enlightener, Navigator sekarang dapat kembali menjelajahi mimpi untuk berpartisipasi dalam berbagai acara eksplorasi, meningkatkan kekuatan mereka dalam mimpi. Dengan mengalahkan Ultimate Dream Devourer, ada peluang untuk mengembalikan stabilitas energi mimpi.",
  str_season_maze_s1_help_disc_102 = "Navigator akan memimpin Enlightener, memanfaatkan kekuatan Kartu Divinasi Mimpi, untuk menelusuri berbagai mimpi dan memicu peristiwa di dalamnya. Sepanjang penjelajahan, Navigator dapat memanggil Aurorian dan mengumpulkan Dream Gear, Dream Orbs, dan sumber daya mimpi lainnya untuk meningkatkan kemampuan mereka. Setelah akhirnya mengalahkan Dream Devourer dan Ultimate Dream Devourer, penjelajahan mimpi akan selesai, menghasilkan hadiah yang berlimpah.",
  str_season_maze_s1_help_disc_201 = "Enlightener akan mengevaluasi kinerja Navigator dalam mimpi dan mencatat skor mereka. Kumpulkan skor yang cukup untuk mendapatkan hadiah yang sesuai.",
  str_season_maze_s1_help_disc_202 = "Setelah setiap eksplorasi, Enlightener akan mencatat skor yang sesuai berdasarkan Level Mimpi dan Kemajuan Eksplorasi. Kumpulkan skor cukup untuk mencapai tonggak tertentu dan dapatkan hadiah yang sesuai. Selain itu, kamu bisa mendapatkan skor ekstra dengan menyelesaikan Dream Quests.",
  str_season_maze_s1_help_disc_203 = "Ketika skor terakumulasi kamu mencapai tonggak tertentu, kamu dapat mengklaim hadiah yang sesuai. Lebih banyak tonggak hadiah akan dibuka pada interval reguler.",
  str_season_maze_s1_help_disc_204 = "Dalam mimpi, ada berbagai Quest Mimpi yang dapat diambil, yang memberikan skor tambahan setelah selesai.",
  str_season_maze_s1_help_disc_301 = "Mimpi dibagi menjadi berbagai level. Semakin tinggi levelnya, semakin sulit tantangannya, dan semakin banyak skor yang diperoleh setelah selesai. Dalam layar Level Mimpi, Anda dapat melihat Ultimate Dream Devourer yang aktif di setiap level untuk merancang strategi eksplorasi Anda sesuai itu.",
  str_season_maze_s1_help_disc_302 = "Kamu akan memulai di Level Mimpi 1 dan membuka level berikutnya setelah menyelesaikan level saat ini, dan beberapa level akan terbuka seiring berjalannya waktu. Fitur Dream Orb akan tersedia saat Level Mimpi 3 dibuka, memberikan dukungan untuk eksplorasi kamu.",
  str_season_maze_s1_help_disc_303 = "Saat memasuki mimpi, kamu perlu memilih 4 Aurorian untuk membentuk formasi awal penjelajahan. Aurorian yang dikerahkan akan mewarisi Level Breakthrough mereka dari luar mimpi tetapi tidak akan mewarisi statistik atau level lain yang telah dikembangkan.",
  str_season_maze_s1_help_disc_401 = "Selama eksplorasi, Navigator dapat mengendalikan diri mereka sendiri dan membawa Enlightener dalam perjalanan.",
  str_season_maze_s1_help_disc_402 = "Enlightener membagi mimpi menjadi berbagai Dunia Mimpi berdasarkan fluktuasi energi mimpi. Navigator hanya dapat berpindah antara Dunia Mimpi, masing-masing memicu peristiwa yang berbeda.",
  str_season_maze_s1_help_disc_403 = "Navigator dapat menggunakan kekuatan Kartu Divinasi Mimpi untuk berpindah antara Dunia Mimpi yang berbeda. Langkah Aksi pada Kartu Divinasi Mimpi menentukan jumlah Dunia Mimpi yang dapat dilalui Navigator, dengan beberapa kartu juga menawarkan sumber daya tambahan atau efek khusus. Di awal setiap ronde, Enlightener akan mengambil sejumlah Kartu Divinasi Mimpi dari dek kartu, dan Navigator dapat memilih satu untuk memainkannya atau menyeretnya langsung ke layar untuk menjalankan efeknya.",
  str_season_maze_s1_help_disc_404 = "Navigator dapat mengumpulkan berbagai sumber daya dalam mimpi. Partikel Mimpi dapat membeli berbagai item, Wawasan Mimpi meningkatkan Level Eksplorasi, Keuntungan Partikel meningkatkan jumlah Partikel Mimpi yang diperoleh per putaran, dan Resonansi menjamin keamanan dan stabilitas navigasi dalam mimpi.",
  str_season_maze_s1_help_disc_405 = "Di Tool Pouch, kamu bisa melihat Aurorian yang dikerahkan dalam eksplorasi ini, Dream Gear yang diperoleh, dan Kartu Divinasi Impian yang ditambahkan ke dek.",
  str_season_maze_s1_help_disc_406 = "Kenangan dan emosi yang ditinggalkan oleh pemimpi asli dibungkus lapis demi lapis dalam energi mimpi, membentuk Dream Orbs. Navigator dapat melihat Dream Orbs yang diperoleh dalam eksplorasi ini di sini dan memasang atau mensintesisnya.",
  str_season_maze_s1_help_disc_407 = "Dream Devourers akan menyerang Navigator setelah sejumlah putaran tertentu. Hanya dengan mengalahkan Dream Devourers, Navigator dapat melanjutkan eksplorasi mimpi mereka. Ultimate Dream Devourer adalah pertemuan terakhir. Kalahkan untuk menyelesaikan eksplorasi ini, mendapatkan skor berdasarkan level mimpi dan kemajuan eksplorasi.",
  str_season_maze_s1_help_disc_408 = "Di sini, Navigator dapat melihat kondisi medan tempur dan informasi musuh dari pertempuran ini, yang memungkinkan mereka untuk menyesuaikan taktik mereka. Navigator dapat memperoleh hadiah yang sesuai setelah menyelesaikan tantangan, tetapi jika gagal, mereka perlu mengkonsumsi Resonance untuk mencoba lagi.",
  str_season_maze_s1_help_disc_409 = "Dream Insight yang diperoleh selama eksplorasi dapat meningkatkan Level Eksplorasi Navigator, menaikkan level Aurorian dan peralatan serta membuka Kartu Divinasi Mimpi dan Item Bantuan Mimpi baru untuk memperkuat eksplorasi mimpi.",
  str_season_maze_s1_help_disc_501 = "Navigator dapat memasuki Dangerous Dream Realms untuk bertempur melawan musuh dan mendapatkan kesempatan untuk memilih satu Dream Gear setelah meraih kemenangan.",
  str_season_maze_s1_help_disc_502 = "Ketika Navigator memasuki Alam Mimpi yang tidak Dikenal, acara acak akan dipicu. Beberapa acara memerlukan pengambilan 3 Kartu Divinasi Mimpi dan penentuan jumlah poin. Keberhasilan dalam penentuan memberikan hadiah yang sesuai.",
  str_season_maze_s1_help_disc_503 = "Saat memasuki Resource Dream Realms, Navigator dapat memperoleh berbagai jenis hadiah sumber daya, termasuk Dream Particles, Dream Insights, dan Dream Orbs. Semakin banyak langkah yang diambil sebelum memasuki Dream Realm ini, semakin banyak hadiahnya.",
  str_season_maze_s1_help_disc_504 = "Saat memasuki Unexplored Dream Realms, Navigator dapat mengerahkan Aurorian untuk melakukan quest demi keuntungan berkelanjutan. Selama penugasan, Aurorian tidak dapat terlibat dalam pertempuran dan akan kembali secara otomatis setelah 5 ronde.",
  str_season_maze_s1_help_disc_505 = "Saat memasuki Treasure Dream Realms, Navigator dapat memilih satu hadiah dari berbagai pilihan untuk diperoleh.",
  str_season_maze_s1_help_disc_506 = "Saat memasuki Terowongan Alam Mimpi, Navigator menunda serangan Dream Devourer selama 1 putaran.",
  str_season_maze_s1_help_disc_507 = "Memasuki Blank Dream Realm tidak akan memicu efek apa pun.",
  str_season_maze_s1_help_disc_508 = "Di Alam Mimpi Divinasi, Navigator dapat menghabiskan Partikel Mimpi untuk mereset atau menghapus Kartu Divinasi Mimpi yang ada.",
  str_season_maze_s1_help_disc_509 = "Di Trade Dream Realms, Navigator dapat saling bertukar berbagai jenis Dream Orbs satu sama lain.",
  str_season_maze_s1_help_disc_510 = "Safe Dream Realm adalah tempat Navigator beristirahat, memungkinkan mereka untuk memanggil Aurorian, membeli barang, membeli obat, atau menghidupkan kembali Aurorian untuk meningkatkan kekuatan mereka. Selain itu, menginfuskan Dream Particles ke dalam Dream Forge dapat membuka item yang lebih kuat untuk tantangan di masa depan.",
  str_season_maze_s1_help_disc_601 = "Navigator dapat memanggil Aurorian untuk bergabung dalam formasi mereka. Aurorian yang diterjunkan akan mewarisi Level Breakthrough mereka dari luar mimpi tetapi tidak akan mewarisi statistik atau level lain yang telah dikembangkan. Tingkatkan Level Eksplorasi Anda untuk meningkatkan level Aurorian dan peralatan mereka dalam mimpi.",
  str_season_maze_s1_help_disc_602 = "Dream Gear adalah pengetahuan berharga dan peninggalan berharga yang ditinggalkan oleh Dream Wayfarers yang cukup berani untuk menjelajahi mimpi di sungai waktu. Ini dapat memicu berbagai efek untuk membantu navigator dalam penjelajahan mimpi mereka.",
  str_season_maze_s1_help_disc_603 = "Navigator dapat menggunakan kekuatan Kartu Divinasi Mimpi untuk berpindah antara Dunia Mimpi yang berbeda. Langkah Aksi pada Kartu Divinasi Mimpi menentukan jumlah Dunia Mimpi yang dapat Navigator pindahi, dengan beberapa kartu juga menawarkan sumber daya tambahan atau efek khusus, termasuk namun tidak terbatas pada Partikel Mimpi, Keuntungan Partikel, Wawasan Mimpi, Resonansi, dll.",
  str_season_maze_s1_help_disc_604 = "Kenangan dan emosi yang ditinggalkan oleh pemimpi asli dibungkus lapis demi lapis dalam energi mimpi, membentuk Dream Orbs. Dream Orbs dapat meningkatkan kekuatan tempur Navigator dalam mimpi, jadi hati-hati jangan sampai Dream Devourer mengambilnya!",
  str_season_maze_s1_help_disc_605 = "Ketika dibawa ke dalam mimpi, barang-barang dunia nyata terkadang terkikis oleh energi mimpi, membentuk Item Bantuan Mimpi. Setiap Item Bantuan Mimpi memiliki efek bantuan yang unik. Gunakan mereka dengan bijaksana untuk mendapatkan dukungan dalam penjelajahan Anda.",
  str_season_maze_s1_guide_warn_90010101 = "Tips: Anda telah berhasil mencapai ruang mimpi yang saling terkait. Di sini, Anda dapat menemukan banyak mimpi yang pernah Anda temui sebelumnya. Silakan ikuti petunjuk dari Enlightener untuk mengalami berbagai acara eksplorasi dan meningkatkan kekuatan Anda. Tujuannya adalah untuk mengalahkan Ultimate Dream Devourer dan memulihkan stabilitas energi mimpi.",
  str_season_maze_s1_guide_warn_90010102 = "Tips: Ketuk di sini untuk mendarat dalam mimpi dan mulai penjelajahan Anda.",
  str_season_maze_s1_guide_warn_90010103 = "Setelah setiap eksplorasi, kinerja Anda dalam mimpi akan dievaluasi, dan Anda akan menerima skor sesuai itu. Anda bisa mendapatkan hadiah eksplorasi yang sesuai setelah skor terakumulasi Anda mencapai tonggak tertentu.",
  str_season_maze_s1_guide_warn_90010104 = "Tips Tambahan: Ketuk pada Info Event untuk detail lebih lanjut tentang Echoes of a Dream.",
  str_season_maze_s1_guide_warn_90010105 = "Tips: Ketuk di sini untuk mendarat dalam mimpi jika Anda sudah siap.",
  str_season_maze_s1_guide_warn_90010201 = "Tips: Sepertinya kamu sudah menemukan bahwa kamu bisa melihat Dream Quest di sini—selesaikan Dream Quest untuk mendapatkan skor yang sesuai.",
  str_season_maze_s1_guide_warn_90010202 = "Tips: Ketika skor terakumulasi kamu mencapai tonggak tertentu, kamu bisa mengklaim hadiah yang sesuai.",
  str_season_maze_s1_guide_warn_90010203 = "Saran: Ada berbagai Quest Impian di dalam mimpi. Sebagai Enlightenermu, saya menyarankan kamu untuk menyelesaikan Quest Impian untuk mendapatkan skor lebih banyak.",
  str_season_maze_s1_guide_warn_90010204 = "Tips: Di sini, kamu dapat melihat skor yang diperlukan untuk tonggak khusus berikutnya dan hadiah yang sesuai. Tonggak tersebut akan terbuka secara otomatis setelah waktu tertentu. Setelah mengklaim semua hadiah saat ini, kamu dapat memeriksa hitungan mundur untuk membuka tonggak berikutnya.",
  str_season_maze_s1_guide_warn_90010301 = "Tips: Biasanya, mimpi dibagi menjadi berbagai level. Semakin tinggi levelnya, tantangan semakin sulit, dan skor yang diperoleh setelah menyelesaikan tantangan juga semakin banyak. Hanya setelah menyelesaikan level saat ini, kamu dapat menantang level berikutnya. Beberapa level akan terbuka secara bertahap setelah periode waktu tertentu.",
  str_season_maze_s1_guide_warn_90010302 = "Analisis situasi sedang berlangsung... Level mimpi saat ini terdeteksi: Level 1. Sebagai Enlightenermu, saya menyarankan kamu untuk memulai tantangan dari level ini.",
  str_season_maze_s1_guide_warn_90010303 = "Analisis situasi sedang berlangsung... Terdeteksi Ultimate Dream Devourer yang menimbulkan kekacauan dalam mimpi ini. Kalahkan Ultimate Dream Devourer untuk mengembalikan ketenangan ke dalam mimpi dan menyelesaikan penjelajahan ini. Ketuk di sini untuk melihat informasi lebih detail tentang Ultimate Dream Devourer.",
  str_season_maze_s1_guide_warn_90010304 = "Tips: Ketuk di sini untuk beralih level mimpi. Selesaikan eksplorasi level saat ini untuk membuka level mimpi berikutnya yang dapat diakses pada waktu yang ditentukan.",
  str_season_maze_s1_guide_warn_90010305 = "Saran: Sekarang, dengan saya di sisi Anda, mulailah penjelajahan Anda dari Dream Level 1.",
  str_season_maze_s1_guide_circle_90010401 = "Analisis situasi sedang berlangsung... Berhasil mendarat di titik awal mimpi. Jangan takut; saya akan berjuang di sampingmu saat kamu menjelajahi mimpi.",
  str_season_maze_s1_guide_circle_90010402 = "Komentar: Saya membagi mimpi menjadi berbagai Alam Mimpi berdasarkan fluktuasi energi mimpi. Harap dicatat bahwa kita hanya bisa berpindah antara Alam Mimpi ini, masing-masing memicu peristiwa yang berbeda. Apakah Anda ingin tahu peristiwa apa yang menanti Anda di Alam Mimpi ini?",
  str_season_maze_s1_guide_warn_90010403 = "Tips: Dengan mengetuk Dream Realm, kamu bisa mengakses nama dan informasi detailnya. Jika kamu menemui Dream Realms yang tidak dikenal nanti, kamu masih bisa mengetuk untuk melihatnya.",
  str_season_maze_s1_guide_warn_90010404 = "Komentar: Saya dapat memantau dan memprediksi aliran energi mimpi, menghasilkan Kartu Ramalan Mimpi ini untuk Anda. Langkah Aksi di sudut kiri atas mewakili jumlah alam mimpi yang dapat Anda lintasi, sementara efek khusus yang melekat pada kartu akan ditampilkan di sudut kanan bawah. Dengan mengikuti instruksi pada Kartu Ramalan Mimpi, Anda akan menghindari terjebak di satu tempat.",
  str_season_maze_s1_guide_warn_90010405 = "Komentar: Pilih Kartu Ramalan Mimpi lalu ketuk Play untuk menjalankan semua efek pada kartu tersebut. Anda juga dapat mencapai efek yang sama dengan menyeret Kartu Ramalan Mimpi ke tengah layar. Di awal setiap putaran, saya akan memilih sejumlah Kartu Ramalan Mimpi dari dek kartu untuk Anda.",
  str_season_maze_s1_guide_warn_90010406 = "Tips: Di sini, kamu bisa melihat semua sumber daya yang telah kamu peroleh selama eksplorasi ini, seperti Partikel Mimpi, Peningkatan Partikel, Resonansi, Tingkat Eksplorasi, Wawasan Mimpi, dll. Tidak apa-apa jika kamu belum familiar dengan mereka sekarang. Saya yakin bahwa seiring kamu semakin mendalami eksplorasi, kamu pasti akan memahami bagaimana cara mendapatkan dan memanfaatkannya.",
  str_season_maze_s1_guide_warn_90010407 = "Tips: Ketuk Info Event untuk detail lebih lanjut.",
  str_season_maze_s1_guide_warn_90010408 = "Tips: Sekarang, silahkan pilih Kartu Ramalan Mimpi untuk dimainkan dan lihat apa yang terjadi.",
  str_season_maze_s1_guide_warn_90010501 = "Komentar: Harap perhatikan Kartu Ramalan Mimpi dengan seksama. Langkah Aksi di sudut kiri atas kartu mewakili jumlah alam mimpi yang dapat Anda jelajahi. Ketika menemui persimpangan, Anda dapat memilih satu jalan untuk melanjutkan. Di ujung beberapa persimpangan terdapat Alam Mimpi Teleportasi, yang dapat mengantarkan Anda ke Alam Mimpi lainnya.",
  str_season_maze_s1_guide_warn_90010502 = "Komentar: Selain Langkah Aksi, Kartu Ramalan Mimpi juga menawarkan hadiah sumber daya yang kaya seperti Partikel Mimpi, Keuntungan Partikel, Resonansi, Wawasan Mimpi, dan lainnya. Angka di bawah ini mewakili jumlah hadiah yang dapat Anda peroleh.",
  str_season_maze_s1_guide_warn_90010503 = "Tips: Di sini, kamu bisa melihat Dream Insights yang diperoleh selama eksplorasi ini. Ketika Dream Insights mencapai standar untuk peningkatan, levelnya akan otomatis naik dan menghapus Dream Insights yang telah terakumulasi. Meningkatkan level Dream Insight dapat meningkatkan level Aurorian dan peralatan serta mendapatkan hadiah sumber daya lainnya.",
  str_season_maze_s1_guide_warn_90010504 = "Peringatan: Untuk memastikan keamananmu dalam mimpi, sangat penting untuk mempertahankan Resonance yang cukup dengan mimpi tersebut. Jika Resonance turun menjadi 0, eksplorasi akan berakhir secara otomatis. Setiap ronde pertempuran menghabiskan 1 poin Resonance. Jika gagal melawan Dream Devourer, kamu juga bisa menghabiskan Resonance untuk mencoba lagi.",
  str_season_maze_s1_guide_warn_90010505 = "Komentar: Partikel Mimpi adalah unit terkecil yang membentuk energi mimpi, dapat ditukarkan dengan berbagai item dalam mimpi. Particle Gain mewakili jumlah Partikel Mimpi yang dapat ditangkap selama acara mimpi. Di akhir setiap putaran, penyelesaian akan terjadi dan memberi Anda jumlah Partikel Mimpi yang sama dengan Particle Gain.",
  str_season_maze_s1_guide_warn_90010506 = "Tips: Di Tool Pouch, kamu bisa memeriksa Aurorian, Dream Gear, dan Kartu Divinasi Impian yang telah ditambahkan ke lineup. Setelah penjelajahan berakhir, Tool Pouch akan dikosongkan.",
  str_season_maze_s1_guide_warn_90010507 = "Peringatan: Dream Devourer telah mendeteksi gerakan kita dan akan menyerang setelah sejumlah putaran. Saya percaya bahwa kamu dapat memerintahkan timmu untuk mengalahkannya. Ultimate Dream Devourer adalah Dream Devourer terakhir yang datang untuk menyerang, dan hanya dengan mengalahkannya eksplorasi ini dapat diakhiri.",
  str_season_maze_s1_guide_warn_90010601 = "Peringatan: Dream Devourer sedang mendekat. Silakan bersiap. Sebagai Enlightenermu, saya akan berjuang bersamamu untuk mengalahkannya. Ingat, penggunaan sumber daya yang ada secara fleksibel akan meningkatkan efektivitas pertempuran kita secara signifikan.",
  str_season_maze_s1_guide_warn_90010602 = "Komentar: Di sini, Anda dapat melihat jenis pertempuran dalam pertemuan ini. Sebagai Enlightener Anda, saya harus mengingatkan Anda bahwa lebih menantang untuk menaklukkan Dream Devourer daripada Dangerous Dream Realms. Anda harus mengalahkan Dream Devourer untuk melanjutkan penjelajahan. Ultimate Dream Devourer mewakili tantangan terakhir, penyelesaian dari tantangan ini menandai akhir dari penjelajahan ini.",
  str_season_maze_s1_guide_warn_90010603 = "Tips: Di sini, kamu bisa melihat kondisi medan perang dan informasi musuh dari pertempuran ini untuk menyesuaikan taktikmu. Sebagai Enlightenermu, saya percaya kamu bisa merancang strategi yang sempurna untuk pertempuran.",
  str_season_maze_s1_guide_warn_90010604 = "Tips: Kemenangan melawan Dream Devourer memberikan hadiah yang melimpah.",
  str_season_maze_s1_guide_warn_90010605 = "Dengan Antisipasi: Mari kita kalahkan Dream Devourer bersama-sama."
}
return config
